import Foundation

/// Codable data models representing the remote VPS status snapshot generated by `/root/vps-storage-watch.sh`
/// at `/root/vps-storage-status.json`.
struct VPSStatusSnapshot: Codable, Equatable, Sendable {
    let generatedAt: String
    let host: String
    let devices: [String: VPSDevice]
    let appDbs: [String: Int64]?
    let cpu: VPSCPU?
    let memory: VPSMemory?
    let swap: VPSSwap?
    let largestDirs: [VPSDirectory]?
    let toolStatuses: [VPSToolStatus]?
    let databaseSamples: [VPSSizeSample]?
    let directorySamples: [VPSSizeSample]?
    /// The server's busiest processes, as its own collector saw them.
    let processes: [VPSProcess]?
    /// The Coolify workloads the server runs.
    let coolify: [VPSCoolifyResource]?

    enum CodingKeys: String, CodingKey {
        case generatedAt = "generated_at"
        case host
        case devices
        case appDbs = "app_dbs"
        case cpu
        case memory
        case swap
        case largestDirs = "largest_dirs"
        case toolStatuses = "tool_statuses"
        case databaseSamples = "database_samples"
        case directorySamples = "directory_samples"
        case processes
        case coolify
    }

    init(
        generatedAt: String,
        host: String,
        devices: [String: VPSDevice],
        appDbs: [String: Int64]? = nil,
        cpu: VPSCPU? = nil,
        memory: VPSMemory? = nil,
        swap: VPSSwap? = nil,
        largestDirs: [VPSDirectory]? = nil,
        toolStatuses: [VPSToolStatus]? = nil,
        databaseSamples: [VPSSizeSample]? = nil,
        directorySamples: [VPSSizeSample]? = nil,
        processes: [VPSProcess]? = nil,
        coolify: [VPSCoolifyResource]? = nil
    ) {
        self.generatedAt = generatedAt
        self.host = host
        self.devices = devices
        self.appDbs = appDbs
        self.cpu = cpu
        self.memory = memory
        self.swap = swap
        self.largestDirs = largestDirs
        self.toolStatuses = toolStatuses
        self.databaseSamples = databaseSamples
        self.directorySamples = directorySamples
        self.processes = processes
        self.coolify = coolify
    }

    private static let isoFormatter: ISO8601DateFormatter = {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime]
        return f
    }()

    private static let isoFractionalFormatter: ISO8601DateFormatter = {
        let f = ISO8601DateFormatter()
        f.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return f
    }()

    var generatedAtDate: Date? {
        Self.isoFractionalFormatter.date(from: generatedAt) ?? Self.isoFormatter.date(from: generatedAt)
    }

    func relativeTimeString(relativeTo now: Date = Date()) -> String {
        guard let date = generatedAtDate else { return generatedAt }
        let formatter = RelativeDateTimeFormatter()
        formatter.unitsStyle = .abbreviated
        return formatter.localizedString(for: date, relativeTo: now)
    }

    var rootDevice: VPSDevice? {
        devices["root"]
    }

    var fleetExtraDevice: VPSDevice? {
        devices["fleet_extra"] ?? devices["fleet-extra"] ?? devices["extra"] ?? devices.values.first {
            $0.mount == "/mnt/fleet-extra" || $0.mount.hasPrefix("/mnt/fleet-extra/")
        }
    }

    var tmpDevice: VPSDevice? {
        devices["tmp"]
    }

    var shmDevice: VPSDevice? {
        devices["shm"]
    }

    /// The one-line answer to "is the server all right?", for the panel strip
    /// and the Maintain tab.  Each number carries its own severity so a
    /// reader sees which one is the problem, not just that something is.
    struct Headline: Equatable {
        var host: String
        var cpuText: String?
        var cpuSeverity: Severity?
        var memoryText: String?
        var memorySeverity: Severity?
        var diskText: String?
        var diskSeverity: Severity?
        var extraDiskText: String?
        var extraDiskSeverity: Severity?
    }

    /// The headline, or nil when the snapshot carries nothing worth showing.
    var headline: Headline? {
        guard !host.isEmpty else { return nil }
        let cpuText = cpu.map { String(format: "%.0f%%", $0.pct) }
        let memoryText = memory.map { String(format: "%.0f%%", $0.usedPercentage) }
        let diskFraction = rootDevice?.usedFraction
        let diskText = diskFraction.map { String(format: "%.0f%% used", $0 * 100) }
        let extraFraction = fleetExtraDevice?.usedFraction
        let extraText = extraFraction.map { String(format: "%.0f%% used", $0 * 100) }
        return Headline(
            host: host,
            cpuText: cpuText,
            cpuSeverity: cpu?.severity,
            memoryText: memoryText,
            memorySeverity: memory?.severity,
            diskText: diskText,
            diskSeverity: diskFraction.map { Severity.forDisk($0) },
            extraDiskText: extraText,
            extraDiskSeverity: extraFraction.map { Severity.forDisk($0) }
        )
    }
}

struct VPSDevice: Codable, Equatable, Sendable {
    let mount: String
    let freeBytes: Int64
    let note: String?

    enum CodingKeys: String, CodingKey {
        case mount
        case freeBytes = "free_bytes"
        case note
    }

    init(mount: String, freeBytes: Int64, note: String? = nil) {
        self.mount = mount
        self.freeBytes = freeBytes
        self.note = note
    }

    /// Attempts to parse total capacity from note (e.g., "301GB disk: ...", "1TB disk: ...")
    var estimatedTotalBytes: Int64? {
        guard let note else { return nil }
        if let match = note.range(of: #"(\d+)\s*(?:GB|TB)"#, options: [.regularExpression, .caseInsensitive]) {
            let str = String(note[match])
            let digits = str.filter { $0.isNumber }
            if let num = Int64(digits) {
                if str.uppercased().contains("TB") {
                    return num * 1_099_511_627_776
                } else {
                    return num * 1_073_741_824
                }
            }
        }
        return nil
    }

    var usedBytes: Int64? {
        guard let total = estimatedTotalBytes, total > 0 else { return nil }
        return max(0, total - freeBytes)
    }

    var usedFraction: Double? {
        guard let total = estimatedTotalBytes, total > 0 else { return nil }
        let used = max(0, total - freeBytes)
        return min(1.0, max(0.0, Double(used) / Double(total)))
    }
}

struct VPSCPU: Codable, Equatable, Sendable {
    let pct: Double
    let load1: Double
    let cores: Int
    let source: String?

    init(pct: Double, load1: Double, cores: Int, source: String? = nil) {
        self.pct = pct
        self.load1 = load1
        self.cores = cores
        self.source = source
    }

    var severity: Severity {
        Severity.forMachineCpu(pct)
    }
}

struct VPSMemory: Codable, Equatable, Sendable {
    let totalBytes: Int64
    let usedBytes: Int64
    let availableBytes: Int64

    enum CodingKeys: String, CodingKey {
        case totalBytes = "total_bytes"
        case usedBytes = "used_bytes"
        case availableBytes = "available_bytes"
    }

    init(totalBytes: Int64, usedBytes: Int64, availableBytes: Int64) {
        self.totalBytes = totalBytes
        self.usedBytes = usedBytes
        self.availableBytes = availableBytes
    }

    var usedPercentage: Double {
        guard totalBytes > 0 else { return 0 }
        return Double(usedBytes) / Double(totalBytes) * 100.0
    }

    var severity: Severity {
        let pct = usedPercentage
        if pct >= 90 { return .hot }
        if pct >= 75 { return .elevated }
        return .calm
    }
}

struct VPSSwap: Codable, Equatable, Sendable {
    let totalBytes: Int64
    let usedBytes: Int64
    let freeBytes: Int64

    enum CodingKeys: String, CodingKey {
        case totalBytes = "total_bytes"
        case usedBytes = "used_bytes"
        case freeBytes = "free_bytes"
    }

    init(totalBytes: Int64, usedBytes: Int64, freeBytes: Int64) {
        self.totalBytes = totalBytes
        self.usedBytes = usedBytes
        self.freeBytes = freeBytes
    }

    var usedPercentage: Double {
        guard totalBytes > 0 else { return 0 }
        return Double(usedBytes) / Double(totalBytes) * 100.0
    }

    var severity: Severity {
        let pct = usedPercentage
        if pct >= 80 { return .hot }
        if pct >= 50 { return .elevated }
        return .calm
    }
}

struct VPSDirectory: Codable, Equatable, Sendable, Identifiable {
    let path: String
    let bytes: Int64

    var id: String { path }

    init(path: String, bytes: Int64) {
        self.path = path
        self.bytes = bytes
    }
}

/// Fixed labels and counts only.  No process arguments or environment values travel here.
struct VPSToolStatus: Codable, Equatable, Sendable, Identifiable {
    enum State: String, Codable, Sendable {
        case running, stopped, absent, unknown
    }
    let id: String
    let name: String
    let state: State
    let count: Int
    /// Why the state is what it is, in words the owner can act on.  An
    /// "unknown" without a reason is a dot nobody can do anything about.
    let reason: String?

    init(id: String, name: String, state: State, count: Int, reason: String? = nil) {
        self.id = id
        self.name = name
        self.state = state
        self.count = count
        self.reason = reason
    }
}

/// One process on the server, as the server's own collector saw it.
///
/// The collector reads executable identity and the kernel's tick counters
/// only: it never reads command arguments, environment variables or
/// credential files, so the name here is the process's name and nothing more.
struct VPSProcess: Codable, Equatable, Sendable, Identifiable {
    let pid: Int
    let name: String
    /// When the process started, in the kernel's own clock.  A pid on its own
    /// can be reused; a pid with its start time identifies one process.
    let startTime: Int64?
    /// The unix account the process runs as.
    let owner: String?
    /// The Coolify workload it belongs to, when it belongs to one.
    let container: String?
    /// The share of one core the process was using.
    let cpuPercent: Double
    let memoryBytes: Int64?

    var id: Int { pid }

    enum CodingKeys: String, CodingKey {
        case pid, name, owner, container
        case startTime = "start_time"
        case cpuPercent = "cpu_percent"
        case memoryBytes = "memory_bytes"
    }

    /// The group the owner thinks in: a Coolify workload, an account, or
    /// something else running on the host.
    var group: String {
        if let container, !container.isEmpty { return container }
        return owner ?? "unknown"
    }
}

/// One Coolify workload on the server.
struct VPSCoolifyResource: Codable, Equatable, Sendable, Identifiable {
    let uuid: String
    let name: String
    let type: String
    let status: String
    let cpuPercent: Double?
    let memoryBytes: Int64?
    let image: String?
    let startedAt: String?

    var id: String { uuid.isEmpty ? name : uuid }

    enum CodingKeys: String, CodingKey {
        case uuid, name, type, status, image
        case cpuPercent = "cpu_percent"
        case memoryBytes = "memory_bytes"
        case startedAt = "started_at"
    }

    /// Whether the workload is the one thing that is wrong.
    var isHealthy: Bool {
        status == "running"
    }
}

/// Existing server observations retain their original Unix timestamps.
struct VPSSizeSample: Codable, Equatable, Sendable {
    let path: String
    let bytes: Int64
    let sampledAt: Double

    enum CodingKeys: String, CodingKey {
        case path, bytes
        case sampledAt = "sampled_at"
    }
}
